begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;select plan(10);
create temporary table reports(label text primary key,id uuid);grant select,insert on reports to authenticated;
insert into auth.users(id,email) values('99999300-0000-0000-0000-000000000001','native-reports@example.test'),('99999300-0000-0000-0000-000000000002','native-reports-foreign@example.test');
set local role authenticated;set local request.jwt.claim.sub='99999300-0000-0000-0000-000000000001';
insert into reports select 'tenant',public.create_business('Native reports');
insert into reports select 'branch',id from public.branches limit 1;
insert into reports select 'customer',public.save_customer((select id from reports where label='tenant'),null,'{"first_name":"Native statement","phone":"998909991"}',array[(select id from reports where label='branch')]);
insert into reports select 'cashbox',public.save_cashbox((select id from reports where label='tenant'),null,gen_random_uuid(),jsonb_build_object('name','Report drawer','cashbox_type','cash','branch_id',(select id from reports where label='branch')));
select public.post_cashbox_entry((select id from reports where label='tenant'),(select id from reports where label='cashbox'),gen_random_uuid(),'opening_balance','1','Native report reserve');
select public.post_payment((select id from reports where label='tenant'),gen_random_uuid(),jsonb_build_object('branch_id',(select id from reports where label='branch'),'customer_id',(select id from reports where label='customer'),'cashbox_id',(select id from reports where label='cashbox'),'amount','100.10','method','cash','paid_at','2026-10-22T12:00:00+05:00'));
set constraints all immediate;
select is(public.financial_dashboard((select id from reports where label='tenant'))->'metrics'->>'received','100.10','Dashboard uses real receipts');
select is(public.financial_dashboard((select id from reports where label='tenant'))->'metrics'->>'cashbox_balance','101.10','Balance includes opening, collections does not');
select is(public.financial_report((select id from reports where label='tenant'),'payments')->>'total','1','Payment report returns real row');
select is(public.financial_report_export((select id from reports where label='tenant'),'payments')->'rows'->0->>'received','100.10','Export retains exact decimal text');
select is(jsonb_typeof(public.financial_report_export((select id from reports where label='tenant'),'payments')->'rows'->0->'received'),'string','Money boundary is text');
select is(public.financial_report((select id from reports where label='tenant'),'payments','{"method":"bank_transfer"}')->>'total','0','Method filtering is enforced');
select is(public.financial_report((select id from reports where label='tenant'),'customer_statement',jsonb_build_object('customer',(select id from reports where label='customer')))->>'total','1','Customer statement includes actual receipt');
select throws_ok($$select public.financial_report((select id from reports where label='tenant'),'payments','{"from":"2026-10-24","to":"2026-10-22"}')$$,'P0001','Invalid report filters','Reversed range rejected');
set local request.jwt.claim.sub='99999300-0000-0000-0000-000000000002';
select throws_ok($$select public.financial_report_export((select id from reports where label='tenant'),'payments')$$,'42501','Financial reporting denied','Foreign tenant cannot export');
set local request.jwt.claim.sub='';
select throws_ok($$select public.financial_dashboard((select id from reports where label='tenant'))$$,'42501','Financial reporting denied','Subjectless dashboard denied');
reset role;select * from finish();rollback;
